import pandas as pd
import numpy as np
from difflib import get_close_matches

def clean(df):
    df = df.copy()
    # Region standardisation
    allowed_regions = ["North", "South", "East", "West"]
    region_map = {}
    for val in df["Region"].astype(str).unique():
        v = val.strip()
        match = next((a for a in allowed_regions if a.lower() == v.lower()), None)
        if match:
            region_map[v] = match
        else:
            close = get_close_matches(v, allowed_regions, n=1, cutoff=0.7)
            region_map[v] = close[0] if close else v
    df["Region"] = df["Region"].astype(str).map(lambda x: region_map.get(x.strip(), x))

    # Price text -> numeric
    def parse_price(p):
        if pd.isna(p):
            return np.nan
        s = str(p).replace("$", "").replace(",", "").strip()
        try:
            return float(s)
        except:
            return np.nan
    df["Price"] = df["Price"].apply(parse_price)

    # Date parsing, coerce invalid
    df["Date"] = pd.to_datetime(df["Date"], errors="coerce", format="%Y-%m-%d")

    # Quantity numeric
    df["Quantity"] = pd.to_numeric(df["Quantity"], errors="coerce")

    # Enforce Revenue = Quantity * Price
    df["Revenue"] = df["Quantity"].astype(float) * df["Price"]
    return df

def answer(df):
    df = df.copy()
    allowed = ["North", "South", "East", "West"]
    # ensure Region is canonical after cleaning
    out = df.groupby("Region")["Quantity"].sum()
    result = {}
    for k, v in out.items():
        k_str = str(k)
        if k_str in allowed and pd.notna(v):
            result[k_str] = int(v)
    return result
